import{_ as a,o,c as t,ag as r}from"./chunks/framework.DJVIMu25.js";const p=JSON.parse('{"title":"数据存储","description":"","frontmatter":{"title":"数据存储"},"headers":[],"relativePath":"zh_Hans/reference/storage.md","filePath":"zh_Hans/reference/storage.md","lastUpdated":1786543805000}'),l={name:"zh_Hans/reference/storage.md"};function d(c,e,i,s,n,m){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="数据存储" tabindex="-1">数据存储 <a class="header-anchor" href="#数据存储" aria-label="Permalink to &quot;数据存储&quot;">​</a></h1><p>JoyMart 提供两种存储模式：YAML 文件（默认，单服）和 MySQL（跨服推荐）。存储模式在 <code>config.yml</code> 的 <code>storage</code> 节点配置，详见 <a href="./../guides/configuration#config-yml">配置文件说明</a>。</p><h2 id="yaml-默认-单服" tabindex="-1">YAML（默认，单服） <a class="header-anchor" href="#yaml-默认-单服" aria-label="Permalink to &quot;YAML（默认，单服）&quot;">​</a></h2><ul><li>玩家数据：<code>plugins/JoyMart/data/players/&lt;uuid&gt;.yml</code></li><li>高分榜：<code>plugins/JoyMart/data/scores/&lt;gameId&gt;.yml</code></li></ul><h2 id="mysql-跨服推荐" tabindex="-1">MySQL（跨服推荐） <a class="header-anchor" href="#mysql-跨服推荐" aria-label="Permalink to &quot;MySQL（跨服推荐）&quot;">​</a></h2><p>在 <code>config.yml</code> 中开启 <code>mysql.enabled: true</code> 并填好连接信息。JoyMart 会自动用 HikariCP 连接池管理连接，所有 BungeeCord 子服共享同一份高分榜与代币数据。</p><h2 id="数据迁移" tabindex="-1">数据迁移 <a class="header-anchor" href="#数据迁移" aria-label="Permalink to &quot;数据迁移&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">迁移命令</p><p><code>/gba migrate mysql</code> 把现有 YAML 数据导入 MySQL；<code>/gba migrate file</code> 反向。</p></div><p>迁移相关命令权限为 <code>gamebox.admin.migrate</code>，详见 <a href="./../guides/commands#管理命令">命令与权限</a>。</p>',9)])])}const u=a(l,[["render",d]]);export{p as __pageData,u as default};
